(function () {
  'use strict';
  window.QUESTION_BANK = Object.assign(window.QUESTION_BANK || {}, {"punctuation-apostrophes-possessives":{"title":"Apostrophes in Possessives","topic":"Punctuation","questions":[{"id":"punctuation-apostrophes-possessives-q0001","version":2,"contentHash":"sha256:4ec4eeb6fb5d1ed460f0d4c26e486184ba03b2e66f09b483241edc5088664c67","question":"Which shows possession correctly?","choices":["the dogs bone","the dogs' bone","the dog's bone","the dog`s bone"],"correct":2,"explanation":{"correct":"Answer: the dog's bone. To show possession for a singular noun, you must add an apostrophe followed by an 's' to the end of the word.","incorrect":[{"choice":"the dogs bone","category":"missing possessive apostrophe","reason":"This phrase is missing an apostrophe, which is required to show that the bone belongs to the dog."},{"choice":"the dogs' bone","category":"incorrect apostrophe placement","reason":"Placing the apostrophe after the 's' is used for plural nouns. Since there is only one dog, the apostrophe must go before the 's'."},"",{"choice":"the dog`s bone","category":"incorrect punctuation mark","reason":"This option uses a backtick instead of an apostrophe. Always use the standard apostrophe key found near the enter key on your keyboard."}]},"studyAid":{"definition":"An apostrophe shows that something belongs to a person, animal, or object. For one owner, add 's to the end of the word.","example":"the cat's toy (one cat), the boy's bike (one boy), the bird's nest (one bird)","strategyClue":"Identify the owner of the object and count how many there are. If the owner is a single person or animal, place the apostrophe before the 's'.","link":"https://www.grammar-monster.com/lessons/apostrophes_show_possession.htm","linkText":"Grammar Monster - Possessive Apostrophes"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-possessives","sequence":1,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-possessives-q0002","version":2,"contentHash":"sha256:54408638f1dc71e8000b38ae4eff06f6677e9a42db21bc0422a38d97086e0369","question":"Which is correct for two dogs owning one bone?","choices":["the dogs bone","the dog's bone","the dogs' bone","the dogs's bone"],"correct":2,"explanation":{"correct":"Answer: the dogs' bone. When a plural noun ends in 's', you show possession by adding only an apostrophe after the 's'.","incorrect":[{"choice":"the dogs bone","category":"missing apostrophe","reason":"This choice treats 'dogs' like an adjective instead of a possessor. Because the dogs own the bone, you must use an apostrophe to show possession."},{"choice":"the dog's bone","category":"singular vs plural","reason":"The apostrophe before the 's' indicates only one dog owns the bone. Since the question asks about two dogs, you need the plural possessive form."},"",{"choice":"the dogs's bone","category":"incorrect plural possessive","reason":"You do not add an extra 's' after the apostrophe when a word is already plural. Simply place the apostrophe after the existing 's' in 'dogs'."}]},"studyAid":{"definition":"To show possession for a plural noun that ends in 's', place an apostrophe after the 's'. If the plural noun does not end in 's', add an apostrophe and an 's'.","example":"one dog's bone, two dogs' bones, the children's toys","strategyClue":"First, determine if the owner is one or many. If the owner is many and the word ends in 's', simply place the apostrophe at the very end of that word.","link":"https://www.grammar-monster.com/lessons/apostrophes_show_possession.htm","linkText":"Grammar Monster - Possessive Apostrophes"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-possessives","sequence":2,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-possessives-q0003","version":3,"contentHash":"sha256:4f902af6f9f5c623db20c2fd2af650568b945852838eaa88d7c85b93eefd8348","question":"Which is correct?","choices":["James's car","James' car","James car","Jamess car"],"correct":0,"explanation":{"correct":"Answer: James's car. When a singular noun ends in 's', the standard rule is to add an apostrophe and an 's' to show possession, making it 'James's'.","incorrect":["",{"choice":"James' car","category":"apostrophe placement error","reason":"While some style guides allow just an apostrophe for names ending in 's', adding the extra 's' is the most common and standard way to show possession for singular names like James."},{"choice":"James car","category":"missing possessive mark","reason":"Without an apostrophe, the word 'James' acts like an adjective, but it doesn't show that the car belongs to him. You need the apostrophe to show ownership."},{"choice":"Jamess car","category":"missing apostrophe","reason":"Simply adding an 's' to the end of a name does not show ownership. You must include the apostrophe to turn the name into a possessive form."}]},"studyAid":{"definition":"To show that something belongs to a person or thing, add an apostrophe and an 's' to the end of the noun, even if it already ends in 's'.","example":"Correct: Jess's book, the dog's bone. Incorrect: Jess book, the dogs bone.","strategyClue":"Ask yourself, 'Who does the car belong to?' If the owner's name ends in 's', check to see which option clearly identifies the owner by attaching the possessive punctuation mark.","link":"https://www.grammar-monster.com/lessons/apostrophes_show_possession.htm","linkText":"Grammar Monster - Possessive Apostrophes"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-possessives","sequence":3,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-possessives-q0004","version":2,"contentHash":"sha256:61ccfcde0556ced96bf4b6eea48f8947227b3bfde8f48a2021af52d4991db03b","question":"Which is correct?","choices":["the childrens toys","the children's toys","the childrens' toys","the children toys"],"correct":1,"explanation":{"correct":"Answer: the children's toys. The word 'children' is an irregular plural noun that does not end in 's', so you must add an apostrophe and an 's' to show possession.","incorrect":[{"choice":"the childrens toys","category":"missing apostrophe","reason":"Since the toys belong to the children, you need an apostrophe to show ownership. Without it, the word just describes the children rather than showing possession."},"",{"choice":"the childrens' toys","category":"incorrect apostrophe placement","reason":"Because 'children' is already plural, the apostrophe must go before the 's'. Placing it after the 's' is only for plural words that end in 's' naturally."},{"choice":"the children toys","category":"missing possessive marker","reason":"You need to show that the toys belong to the children. Adding 's preceded by an apostrophe marks the children as the owners of the toys."}]},"studyAid":{"definition":"To show possession for plural nouns, add an apostrophe and an 's' if the word does not end in 's'. If the plural word already ends in 's', just add an apostrophe at the end.","example":"the dog's ball (singular), the men's hats (irregular plural), the dogs' bowls (plural ending in s)","strategyClue":"Ask yourself: 'Who owns the item?' Then, check if that word is plural or singular, and look for an 's' at the end of the word before choosing where to place the apostrophe.","link":"https://www.grammar-monster.com/lessons/apostrophes_show_possession.htm","linkText":"Grammar Monster - Possessive Apostrophes"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-possessives","sequence":4,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-possessives-q0005","version":3,"contentHash":"sha256:4e25b8c67416437de4253981078a47df62f9e4dc702fc42acaa3969b3117365d","question":"Which is incorrect?","choices":["the cat's whiskers","the cats' whiskers","the cats whiskers","the cat whiskers"],"correct":2,"explanation":{"correct":"Answer: the cats whiskers. This phrase is missing an apostrophe, which is required to show possession because the whiskers belong to the cat.","incorrect":[{"choice":"the cat's whiskers","category":"correct singular possessive","reason":"This is actually a correct way to write the phrase if there is one cat. The apostrophe before the 's' shows that the whiskers belong to that one cat."},{"choice":"the cats' whiskers","category":"correct plural possessive","reason":"This is also a correct way to write the phrase if there are multiple cats. The apostrophe after the 's' shows that the whiskers belong to more than one cat."},"",{"choice":"the cat whiskers","category":"noun as adjective","reason":"While 'cat whiskers' might be used as a label, in this sentence structure, the whiskers possess a relationship to the animal, making it different from a possessive form."}]},"studyAid":{"definition":"To show that something belongs to a noun, add an apostrophe. Place the apostrophe before the 's' for one owner or after the 's' for multiple owners.","example":"One dog's bone (singular), two dogs' bones (plural), one boy's toy (singular), three boys' toys (plural).","strategyClue":"Ask yourself: 'Do the whiskers belong to the cat?' If the answer is yes, you must use an apostrophe to show that ownership.","link":"https://www.grammar-monster.com/lessons/apostrophes_show_possession.htm","linkText":"Grammar Monster - Possessive Apostrophes"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"spot the exception, then explain why the other choices follow the rule","estimatedTimeSeconds":35,"reviewPriority":"high","sourceSet":"punctuation-apostrophes-possessives","sequence":5,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-possessives-q0006","version":3,"contentHash":"sha256:7032e3430d68b4a0f457e6ab944b89e249112270cc16693490c7f8de05145132","question":"Which is correct?","choices":["its tail","it's tail","its' tail","it tail"],"correct":0,"explanation":{"correct":"Answer: its tail. 'Its' is a possessive pronoun that shows ownership, meaning the tail belongs to the animal or object, so no apostrophe is needed.","incorrect":["",{"choice":"it's tail","category":"confusing contraction","reason":"The word 'it's' is a contraction for 'it is' or 'it has.' Replacing it in the sentence creates 'it is tail,' which does not make sense."},{"choice":"its' tail","category":"misplaced apostrophe","reason":"Apostrophes are never used with the possessive pronoun 'its.' The apostrophe here is unnecessary and grammatically incorrect."},{"choice":"it tail","category":"missing possessive form","reason":"The word 'it' needs to show that the tail belongs to the subject. 'It' is just a pronoun, but 'its' shows the necessary possession."}]},"studyAid":{"definition":"The word 'its' shows ownership, while 'it's' is a shortened way to say 'it is' or 'it has.'","example":"The dog wagged its tail. (ownership) / It's a sunny day. (it is)","strategyClue":"Try replacing the word in the blank with 'it is.' If the sentence makes sense, you need the apostrophe; if it does not, you need the possessive form without an apostrophe.","link":"https://www.grammar-monster.com/lessons/apostrophes_show_possession.htm","linkText":"Grammar Monster - Possessive Apostrophes"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-possessives","sequence":6,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-possessives-q0007","version":2,"contentHash":"sha256:5fef15aca3fd46659240ae4b3db3546f3ebea7ec5ef7c5f8e7bb82b9967b7b6f","question":"Which is correct?","choices":["the mouse's cheese","the mouses cheese","the mice's cheese","the mices cheese"],"correct":0,"explanation":{"correct":"Answer: the mouse's cheese. When a noun is singular, you add an apostrophe and an 's' to show ownership. Since there is only one mouse, 'mouse's' is the correct form.","incorrect":["",{"choice":"the mouses cheese","category":"missing apostrophe","reason":"This choice is missing the apostrophe entirely. To show that the cheese belongs to the mouse, you must include the apostrophe before the 's'."},{"choice":"the mice's cheese","category":"wrong number noun","reason":"The word 'mice' is plural. This sentence refers to a single mouse, so you should use the singular form 'mouse' before adding the apostrophe and 's'."},{"choice":"the mices cheese","category":"plural possessive error","reason":"This uses the plural form 'mices' which is not a standard English word, and it also lacks the necessary apostrophe to show possession."}]},"studyAid":{"definition":"To show that something belongs to a singular person, place, or thing, add an apostrophe followed by an 's' to the end of the word.","example":"the dog's toy (one dog), the cat's tail (one cat), the boy's bike (one boy)","strategyClue":"First, determine if you are talking about one item or many items. If there is only one, write the word normally and then add the apostrophe and 's'.","link":"https://www.grammar-monster.com/lessons/apostrophes_show_possession.htm","linkText":"Grammar Monster - Possessive Apostrophes"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-possessives","sequence":7,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-possessives-q0008","version":2,"contentHash":"sha256:bd880dfe16dcd98edc4bb04bc5761d01a3cf989cd6b0655f23b66282943c8dc3","question":"Which is correct?","choices":["my parents car","my parent's car","my parents' car","my parentss car"],"correct":2,"explanation":{"correct":"Answer: my parents' car. Since 'parents' is plural and ends in 's', you must place the apostrophe after the 's' to show that the car belongs to both of them.","incorrect":[{"choice":"my parents car","category":"missing possessive apostrophe","reason":"This phrase suggests the car is just labeled 'parents,' but it doesn't show ownership. To show the car belongs to your parents, you must include an apostrophe."},{"choice":"my parent's car","category":"singular possessive error","reason":"This implies there is only one parent. Because the word is 'parents' (plural), the apostrophe must go after the 's' rather than before it."},"",{"choice":"my parentss car","category":"spelling error","reason":"Adding an extra 's' at the end of the word creates a spelling error. Use the plural form 'parents' before adding the apostrophe."}]},"studyAid":{"definition":"To show possession for a plural noun ending in 's', add an apostrophe after the final 's'. For singular nouns, add an apostrophe followed by an 's'.","example":"one dog's bowl (singular), two dogs' bowls (plural), the bird's song (singular), the birds' songs (plural)","strategyClue":"First, identify if the noun is singular (one person) or plural (more than one). If it is plural and already ends in 's', place the apostrophe at the very end of the word.","link":"https://www.grammar-monster.com/lessons/apostrophes_show_possession.htm","linkText":"Grammar Monster - Possessive Apostrophes"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-possessives","sequence":8,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-possessives-q0009","version":3,"contentHash":"sha256:8ea67961169c5acbf45eb158532fec1004191279801456967b524552fd8a54cb","question":"Which is incorrect?","choices":["the boss's desk","the boss' desk","the bosses desk","the bosses' desk"],"correct":2,"explanation":{"correct":"Answer: the bosses desk. This phrase is incorrect because it lacks an apostrophe to show ownership. When someone owns something, you must use an apostrophe to show that possession.","incorrect":[{"choice":"the boss's desk","category":"singular possessive","reason":"This is a correct way to show that one boss owns the desk. Adding 's after the singular noun is the standard rule."},{"choice":"the boss' desk","category":"alternative singular possessive","reason":"This is also an acceptable way to show possession for a singular noun ending in 's'. It is not incorrect."},"",{"choice":"the bosses' desk","category":"plural possessive","reason":"This correctly shows that multiple bosses share the desk. Since the noun ends in 's', the apostrophe goes after the final 's'."}]},"studyAid":{"definition":"Use an apostrophe to show ownership. If the owner is one person, add 's; if the owners are a group ending in s, just add an apostrophe at the end.","example":"the dog's toy (one dog), the dogs' toys (many dogs), James's book (one person named James)","strategyClue":"Ask yourself who owns the object and how many owners there are. Look for the apostrophe's position to see if it correctly indicates who the owner is.","link":"https://www.grammar-monster.com/lessons/apostrophes_show_possession.htm","linkText":"Grammar Monster - Possessive Apostrophes"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"spot the exception, then explain why the other choices follow the rule","estimatedTimeSeconds":35,"reviewPriority":"high","sourceSet":"punctuation-apostrophes-possessives","sequence":9,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-possessives-q0010","version":2,"contentHash":"sha256:38af76c2732edb165e054fc89463246a337d7264e09e99720b2a01e861ee0707","question":"Which is correct?","choices":["the knife's edge","the knives edge","the knives' edge","the knifes edge"],"correct":0,"explanation":{"correct":"Answer: the knife's edge. Because 'knife' is a singular noun, you form the possessive by adding an apostrophe and an 's' ('s).","incorrect":["",{"choice":"the knives edge","category":"missing apostrophe","reason":"When a word shows possession, it needs an apostrophe to show that something belongs to it. Without the mark, it is just a plural noun."},{"choice":"the knives' edge","category":"plural possessive error","reason":"This form is used for plural nouns (more than one knife). Since the sentence refers to a single knife, the apostrophe must come before the 's'."},{"choice":"the knifes edge","category":"missing apostrophe","reason":"While you added an 's', you missed the apostrophe! The apostrophe is a required punctuation mark to show ownership, not just an 's'."}]},"studyAid":{"definition":"To show ownership for a singular noun, add an apostrophe followed by an 's' to the end of the word.","example":"the dog's toy (one dog), the cat's tail (one cat), the friend's house (one friend)","strategyClue":"First, count how many items own the object. If there is only one item, write the word exactly as it is, then add an apostrophe and an 's'.","link":"https://www.grammar-monster.com/lessons/apostrophes_show_possession.htm","linkText":"Grammar Monster - Possessive Apostrophes"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-possessives","sequence":10,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-possessives-q0011","version":2,"contentHash":"sha256:71bc725075489ea571b8d3a87a6201161f08fac9b6335dca4f5b1eaf6ebf6805","question":"Which is correct?","choices":["yours truly","your's truly","yours' truly","you'rs truly"],"correct":0,"explanation":{"correct":"Answer: yours truly. The word 'yours' is a possessive pronoun, which already shows ownership and never requires an apostrophe.","incorrect":["",{"choice":"your's truly","category":"incorrect apostrophe placement","reason":"The word 'your' is an adjective, and adding an apostrophe does not make it a noun or a correct possessive form here."},{"choice":"yours' truly","category":"extra apostrophe usage","reason":"You only add an apostrophe to show possession for nouns. 'Yours' is already possessive, so it does not need any extra punctuation."},{"choice":"you'rs truly","category":"incorrect apostrophe placement","reason":"Apostrophes are used to replace missing letters in contractions or to show possession in nouns. This placement is not used in standard English."}]},"studyAid":{"definition":"Possessive pronouns like yours, mine, hers, and ours describe ownership and never use apostrophes.","example":"Correct: This is yours. Incorrect: This is your's.","strategyClue":"Ask yourself if the word represents a noun that owns something or if it is a pronoun. If it is a pronoun like 'yours', remember that it is already complete and does not need an apostrophe.","link":"https://www.grammar-monster.com/lessons/apostrophes_show_possession.htm","linkText":"Grammar Monster - Possessive Apostrophes"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-possessives","sequence":11,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-possessives-q0012","version":2,"contentHash":"sha256:06e647926cc5c65d7f480b6cc0385590802ab11956439abb6338700c59709c86","question":"Which is correct?","choices":["the deer's antlers","the deers antlers","the deers' antlers","the deer antlers"],"correct":0,"explanation":{"correct":"Answer: the deer's antlers. Because 'deer' is the singular form (and also the plural form), you must add an apostrophe and an 's' to show possession for the animal's body parts.","incorrect":["",{"choice":"the deers antlers","category":"missing apostrophe","reason":"This phrase needs an apostrophe to show possession. Without it, 'deers' looks like a simple plural rather than an owner."},{"choice":"the deers' antlers","category":"misplaced apostrophe","reason":"Placing the apostrophe after the 's' is for words that end in 's' naturally in their plural form. Since 'deer' does not end in 's', the apostrophe goes before the 's'."},{"choice":"the deer antlers","category":"missing possessive marker","reason":"This implies the antlers are simply named 'deer antlers' rather than belonging to the deer. To show that the antlers belong to the animal, you need the possessive form."}]},"studyAid":{"definition":"To show possession, add an apostrophe and an 's' to most nouns. If the word already ends in 's' because it is plural, just add the apostrophe after the 's'.","example":"the dog's toy, the birds' nests, the child's hat","strategyClue":"Ask yourself: 'Do the antlers belong to the deer?' If the answer is yes, use the apostrophe to show that ownership, even if the word 'deer' looks like a plural word.","link":"https://www.grammar-monster.com/lessons/apostrophes_show_possession.htm","linkText":"Grammar Monster - Possessive Apostrophes"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-possessives","sequence":12,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-possessives-q0013","version":3,"contentHash":"sha256:3434a635896d6e33c00588b5657c0492fbdbc178b3b1b15aa4b70f9d91d7f3c8","question":"Which is incorrect?","choices":["the student's desk","the students' desk","the students desk","the student's desks"],"correct":2,"explanation":{"correct":"Answer: the students desk. This choice is incorrect because it lacks an apostrophe. When showing possession, an apostrophe must be used to indicate ownership, which is missing here.","incorrect":[{"choice":"the student's desk","category":"correct singular possessive","reason":"This is actually correct! The apostrophe before the 's' shows that one single student owns the desk."},{"choice":"the students' desk","category":"correct plural possessive","reason":"This is also correct! Placing the apostrophe after the 's' shows that multiple students share one desk."},"",{"choice":"the student's desks","category":"correct possessive plural","reason":"This is a grammatically correct way to say that one student owns more than one desk."}]},"studyAid":{"definition":"Use an apostrophe to show ownership. If one person owns something, put the apostrophe before the 's'; if multiple people own it, put the apostrophe after the 's'.","example":"The dog's bone (one dog), The dogs' bone (many dogs), The boy's toys (one boy)","strategyClue":"Look at the noun before the apostrophe to see if it is singular or plural, then check if the apostrophe is placed in the correct spot to show ownership.","link":"https://www.grammar-monster.com/lessons/apostrophes_show_possession.htm","linkText":"Grammar Monster - Possessive Apostrophes"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"spot the exception, then explain why the other choices follow the rule","estimatedTimeSeconds":35,"reviewPriority":"high","sourceSet":"punctuation-apostrophes-possessives","sequence":13,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-possessives-q0014","version":2,"contentHash":"sha256:efb376154e2950c783c6a85ae45aaa0a92599d77d9f52680160d067f2554e096","question":"Which is correct?","choices":["someone's phone","someones phone","someone' phone","someones' phone"],"correct":0,"explanation":{"correct":"Answer: someone's phone. When a singular indefinite pronoun like 'someone' shows possession, you add an apostrophe followed by an 's' to the end of the word.","incorrect":["",{"choice":"someones phone","category":"missing apostrophe","reason":"This phrase needs an apostrophe to show that the phone belongs to someone. Without it, the word looks like a plural noun rather than a possessive one."},{"choice":"someone' phone","category":"misplaced apostrophe","reason":"Adding only an apostrophe without the 's' is incorrect for singular words ending in a consonant. You must add both the apostrophe and the 's' to show possession."},{"choice":"someones' phone","category":"incorrect plural apostrophe","reason":"Placing the apostrophe after the 's' is used for plural nouns, but 'someone' is singular. This structure creates confusion about who the phone belongs to."}]},"studyAid":{"definition":"To show possession for a singular person or pronoun, add an apostrophe and an 's' to the end of the word.","example":"Correct: The dog's toy, Someone's book. Incorrect: The dogs toy, Someones book.","strategyClue":"Ask yourself: 'Does one person own this?' If the answer is yes, ensure the apostrophe appears before the 's' at the very end of the name or pronoun.","link":"https://www.grammar-monster.com/lessons/apostrophes_show_possession.htm","linkText":"Grammar Monster - Possessive Apostrophes"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-possessives","sequence":14,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-possessives-q0015","version":3,"contentHash":"sha256:87ab3197f38d33aad96f80092850193f6fe9304eb5a97dcff996ed5bacc4a920","question":"Which is correct?","choices":["the witness's statement","the witness' statement","the witnesss statement","the witness statement"],"correct":0,"explanation":{"correct":"Answer: the witness's statement. For singular nouns ending in 's', you add an apostrophe followed by an 's' (apostrophe-s) to show possession.","incorrect":["",{"choice":"the witness' statement","category":"missing apostrophe-s","reason":"While some style guides allow an apostrophe alone for words ending in 's', adding 's' is the standard rule for singular nouns to show clear possession."},{"choice":"the witnesss statement","category":"missing apostrophe","reason":"You must include an apostrophe to show ownership. Without one, the word just looks like a plural noun, which does not fit here."},{"choice":"the witness statement","category":"missing possessive marker","reason":"Using 'witness' as an adjective doesn't show that the statement belongs to the witness. You need the apostrophe and 's' to indicate possession."}]},"studyAid":{"definition":"To make a singular noun possessive, add an apostrophe and an 's' to the end of the word, even if the word already ends in 's'.","example":"the boss's desk, the bus's tire, the cactus's needles","strategyClue":"Look at the noun before the thing being owned. If it is singular, always add an apostrophe and an 's' to show that the noun is the owner, regardless of its last letter.","link":"https://www.grammar-monster.com/lessons/apostrophes_show_possession.htm","linkText":"Grammar Monster - Possessive Apostrophes"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-possessives","sequence":15,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-apostrophes-possessives-q0016","version":2,"contentHash":"sha256:66fea323260002d70f7ce7f70405194bb12f9d9bce305f896b4eb0b372be1d65","question":"Which shows that the candy belongs to Shirley?","choices":["Shirley’s candy","Shirleys’ candy not","Shirleys candys’","Shirleys’s candy"],"correct":0,"explanation":{"correct":"Answer: Shirley’s candy. Use an apostrophe followed by an 's' to show that a singular noun owns something. Since there is only one Shirley, we add ’s to her name.","incorrect":["",{"choice":"Shirleys’ candy not","category":"misplaced apostrophe","reason":"Placing the apostrophe after the 's' is used for plural nouns. Also, the word 'not' is unnecessary and makes the phrase confusing."},{"choice":"Shirleys candys’","category":"incorrect pluralization","reason":"This looks like you are talking about many Shirleys and many candies. We only need an apostrophe on the owner's name, not on the item being owned."},{"choice":"Shirleys’s candy","category":"extra apostrophe usage","reason":"You only need one apostrophe when showing possession. Adding an extra one after the 's' makes the word difficult to read and grammatically incorrect."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-possessives","sequence":16,"sourceFile":"Advanced-5_grammer and usage.pdf","sourceQuestionNumber":1,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"To show possession for a singular name, add an apostrophe and an 's' to the end of the word.","example":"The dog's bowl (one dog), Sam's hat (one Sam), the cat's toy (one cat)","strategyClue":"Identify the owner of the object, then see which option correctly attaches the possession mark to that specific name without adding extra symbols or changing the spelling.","link":"","linkText":""}},{"id":"punctuation-apostrophes-possessives-q0017","version":2,"contentHash":"sha256:5c6bfe58f4d6faaa1f45184782c577788559e20637d36405b173091fd8a189e7","question":"Which word is both plural and possessive?","choices":["animal’s","giraffes","girl’s","children’s"],"correct":3,"explanation":{"correct":"Answer: children’s. The word 'children' is the irregular plural of 'child,' and adding an apostrophe followed by an 's' shows possession for that group.","incorrect":[{"choice":"animal’s","category":"singular possessive noun","reason":"This form uses an apostrophe before the 's', which indicates possession for only one animal. It is also misspelled with a space."},{"choice":"giraffes","category":"simple plural noun","reason":"This is a regular plural noun, meaning there is more than one giraffe. However, it lacks an apostrophe, so it shows no ownership."},{"choice":"girl’s","category":"singular possessive noun","reason":"The apostrophe before the 's' shows that only one girl owns something. It is singular, not plural."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-possessives","sequence":17,"sourceFile":"Advanced-5_grammer and usage.pdf","sourceQuestionNumber":4,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"A plural possessive noun refers to more than one person, place, or thing owning something. If the plural word does not end in 's', add an apostrophe and an 's' to make it possessive.","example":"Correct: men’s hats, children’s toys, mice’s tails. Incorrect: childrens’s, childs’ toys.","strategyClue":"First, identify if the base word stands for one or many. Then, look for an apostrophe that follows the plural form to show that the whole group owns the object.","link":"","linkText":""}},{"id":"punctuation-apostrophes-possessives-q0018","version":2,"contentHash":"sha256:acdc4590f69717e00cf02f15ead7daea291a3413234571f6c2a9594bcf4dae37","question":"Which shows that the backpack belongs to Andy?","choices":["Andy’s backpack","Andys’ backpack","Andys backpack","Andys’s backpack"],"correct":0,"explanation":{"correct":"Answer: Andy’s backpack. To show possession for a singular name ending in any letter except s, you add an apostrophe and an s ('s) to the name.","incorrect":["",{"choice":"Andys’ backpack","category":"misplaced apostrophe","reason":"The apostrophe after the 's' is used for plural nouns ending in s. Since there is only one Andy, the apostrophe must go before the 's'."},{"choice":"Andys backpack","category":"missing apostrophe","reason":"Without an apostrophe, the word 'Andys' looks like a plural noun rather than showing ownership. An apostrophe is required to show the backpack belongs to Andy."},{"choice":"Andys’s backpack","category":"extra apostrophe usage","reason":"Adding an apostrophe and another 's' after a name already ending in 'y' is incorrect. We only add the apostrophe and the single 's' to the name."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-possessives","sequence":18,"sourceFile":"Proficient-4_grammer and usage.pdf","sourceQuestionNumber":3,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"To show ownership for a singular noun, add an apostrophe and an s ('s) to the end of the word.","example":"The dog's bone, Sarah's book, The cat's toy.","strategyClue":"Identify the owner and ask yourself: 'Is there only one owner?' If the answer is yes, place the apostrophe immediately after the name, then add the s.","link":"","linkText":""}},{"id":"punctuation-apostrophes-possessives-q0019","version":2,"contentHash":"sha256:d94bedd5bebe22302cb6532a8dc62ac83585ce663ed309ed98781a55eb49ed6c","question":"Which word pair has a possessive noun?","choices":["can’t wait","haven’t ever","wasn’t cold","Todd’s car"],"correct":3,"explanation":{"correct":"Answer: Todd’s car. The apostrophe in 'Todd’s' shows ownership, meaning the car belongs to Todd. This is a possessive noun.","incorrect":[{"choice":"can’t wait","category":"contraction usage","reason":"The apostrophe in 'can’t' replaces the letter 'o' in 'cannot'. It is a contraction, not a word showing possession."},{"choice":"haven’t ever","category":"contraction usage","reason":"The apostrophe in 'haven’t' stands for the missing letter 'o' in 'have not'. This is a shortened verb form, not a possessive."},{"choice":"wasn’t cold","category":"contraction usage","reason":"In 'wasn’t', the apostrophe takes the place of the letter 'o' in 'was not'. Contractions like this are used to combine words, not to show that someone owns something."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-possessives","sequence":19,"sourceFile":"Proficient-6_grammer and usage.pdf","sourceQuestionNumber":9,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"A possessive noun uses an apostrophe followed by an 's' to show that a person, animal, or thing owns or has something. Contractions use apostrophes to show where letters have been removed when joining two words together.","example":"Possessive: Sarah’s book, the cat’s toy. Contraction: she’s (she is), it’s (it is).","strategyClue":"Ask yourself: Does this word show that something belongs to someone? If you can replace the apostrophe part with 'is' or 'not', it is likely a contraction, not a possessive noun.","link":"","linkText":""}},{"id":"punctuation-apostrophes-possessives-q0020","version":2,"contentHash":"sha256:342a5e8e2f0fffe3c1832edafb9062fcb1e6e533be32e904cbe139c3691bbd2a","question":"Which sentence is punctuated correctly to show plural possession?","choices":["The boys’ uniform’s were worn and dirty, but the boy’s attitudes were still confident.","The boys’ uniforms were worn and dirty, but the boys’ attitudes were still confident.","The boys uniform’s were worn and dirty, but the boys attitudes were still confident.","The boy’s uniforms were worn and dirty, but the boys attitudes were still confident."],"correct":1,"explanation":{"correct":"Answer: The boys’ uniforms were worn and dirty, but the boys’ attitudes were still confident. When a noun is plural and ends in 's', add only an apostrophe after the 's' to show possession.","incorrect":[{"choice":"The boys’ uniform’s were worn and dirty, but the boy’s attitudes were still confident.","category":"incorrect apostrophe placement","reason":"Adding an apostrophe before the 's' in 'uniform's' makes it look like a contraction for 'uniform is'. Also, 'boy's' is singular, but the sentence refers to multiple boys."},"",{"choice":"The boys uniform’s were worn and dirty, but the boys attitudes were still confident.","category":"missing apostrophes","reason":"Possession requires an apostrophe. 'Boys uniform's' uses an apostrophe to show it is a contraction, which doesn't make sense, and the second part lacks an apostrophe entirely."},{"choice":"The boy’s uniforms were worn and dirty, but the boys attitudes were still confident.","category":"singular vs plural possession","reason":"'Boy’s' implies only one boy, but the context shows multiple boys. Also, 'boys attitudes' needs an apostrophe to show that the attitudes belong to the boys."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","mechanics","editing"],"feedbackFocus":"use the mechanics clue and compare each answer choice to the rule","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-possessives","sequence":20,"sourceFile":"Advanced-3_Mechanics and Punctuation.pdf","sourceQuestionNumber":9,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"To show possession for a plural noun ending in 's', place the apostrophe after the final 's'. Do not add another 's'.","example":"The teachers' lounge (many teachers), the dogs' bowls (many dogs), the cats' toys (many cats)","strategyClue":"First, identify if the noun is singular (one) or plural (many). If it is plural and ends in 's', place your apostrophe outside and to the right of that 's' to show ownership.","link":"","linkText":""}},{"id":"punctuation-apostrophes-possessives-q0021","version":2,"contentHash":"sha256:5de69186f9ae4f74d52d83bb3e59bf6826e18b957cdb647ddb84705c425f07d9","question":"Which words means the uniforms belong to both girls?","choices":["the girl’s uniforms","the girls’ uniforms’","the girls uniforms","the girls’ uniforms"],"correct":3,"explanation":{"correct":"Answer: the girls’ uniforms. When a plural noun ends in 's', show possession by placing the apostrophe after the 's'. Since there are multiple girls who own the uniforms, the apostrophe goes at the very end of 'girls'.","incorrect":[{"choice":"the girl’s uniforms","category":"singular possessive error","reason":"Placing the apostrophe before the 's' makes it singular. This would mean the uniforms belong to only one girl, not both."},{"choice":"the girls’ uniforms’","category":"double possessive error","reason":"You only need one apostrophe to show ownership. Adding an apostrophe after 'uniforms' incorrectly implies that the uniforms themselves own something."},{"choice":"the girls uniforms","category":"missing possessive apostrophe","reason":"Without an apostrophe, the word 'girls' is just a plural noun, not a possessive one. You need the apostrophe to show that the uniforms belong to them."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","mechanics","editing"],"feedbackFocus":"use the mechanics clue and compare each answer choice to the rule","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-possessives","sequence":21,"sourceFile":"Proficient-3_Mechanics and Punctuation.pdf","sourceQuestionNumber":10,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"To show possession for a plural noun ending in 's', add an apostrophe after the 's'. If the noun is singular, add an apostrophe before the 's'.","example":"The dog's bone (one dog), The dogs' bones (multiple dogs), The boys' hats (multiple boys)","strategyClue":"Ask yourself: 'Is there more than one person owning the item?' If yes, write the plural word first (like 'girls'), then add the apostrophe to the end of that word.","link":"","linkText":""}},{"id":"punctuation-apostrophes-possessives-q0022","version":3,"contentHash":"sha256:d7ac231772d990d1085a5af6cc04db673197441565cfb37645b330089cf6d8f6","question":"Which sentence is punctuated correctly to show plural possession?","choices":["The actors costume’s were missing, but the actors attitudes were still positive and h opeful.","The actors’costume’s were missing, but the actor’s attitudes were still positive and hopeful.","The actors’costumes were missing, but the actors’attitudes were still positive and hopeful.","The actor’s costumes we re missing, but the actors attitudes were still positive and hopeful."],"correct":2,"explanation":{"correct":"Answer: The actors’ costumes were missing, but the actors’ attitudes were still positive and hopeful. When a plural noun ends in 's', you show possession by adding only an apostrophe after the 's'.","incorrect":[{"choice":"The actors costume’s were missing, but the actors attitudes were still positive and h opeful.","category":"incorrect apostrophe placement","reason":"Placing the apostrophe before the 's' in 'costume's' makes it look like a singular noun that belongs to one costume. Since there are multiple actors and multiple costumes, the apostrophe must go after the 's' in 'actors'."},{"choice":"The actors’costume’s were missing, but the actor’s attitudes were still positive and hopeful.","category":"misused possessive punctuation","reason":"Adding an apostrophe to 'costume's' is unnecessary because the costume is not owning anything. Additionally, the sentence changes 'actors' to 'actor's', which incorrectly suggests only one actor has the attitudes."},"",{"choice":"The actor’s costumes we re missing, but the actors attitudes were still positive and hopeful.","category":"singular vs plural possessive","reason":"The first part uses 'actor's' (singular), implying only one actor, and the second part lacks an apostrophe entirely for 'actors', which is required to show they own the attitudes."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","mechanics","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-possessives","sequence":22,"sourceFile":"Advanced-1_language Usage.pdf","sourceQuestionNumber":35,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"To show possession for a plural noun ending in 's', simply place an apostrophe after the final 's'. For singular nouns, place the apostrophe before the 's'.","example":"one dog's bone (singular), ten dogs' bones (plural), the teachers' lounge (plural)","strategyClue":"First, identify if the noun is singular or plural. If it ends in 's' because it is plural, place your apostrophe outside the word at the very end.","link":"","linkText":""}},{"id":"punctuation-apostrophes-possessives-q0023","version":3,"contentHash":"sha256:fe77a343b9b4d14892d4ddece681c27d00574669c19cab45de3d57df9214a2db","question":"Your teacher assigns the topic “The Interstate Highway System” for a research paper. Which statement would not be in the contentof the paper?","choices":["The U.S. is a Nation of Drivers","My Car’s Blowouton the Highway","The Federal-Aid Highway Actof 1956","The Birth of the Interstate Highway System"],"correct":1,"explanation":{"correct":"Answer: My Car’s Blowout on the Highway. This is a personal anecdote rather than a factual topic about the history or impact of the Interstate Highway System.","incorrect":[{"choice":"The U.S. is a Nation of Drivers","category":"relevant historical context","reason":"This is a relevant theme for a research paper on highways, as the highway system was built specifically to support the nation's growing reliance on automobiles."},"",{"choice":"The Federal-Aid Highway Actof 1956","reason":"\"The Federal-Aid Highway Actof 1956\" is a correctly formed possessive or acceptable noun phrase, so it is not the incorrect choice the prompt asks for."},{"choice":"The Birth of the Interstate Highway System","category":"appropriate research topic","reason":"This is a central topic for a paper. Researching the 'birth' of the system allows for an explanation of how and why the highways were originally planned."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"passage-context","skills":["punctuation","mechanics","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-possessives","sequence":23,"sourceFile":"Advanced-1_language Usage.pdf","sourceQuestionNumber":48,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"A research paper topic should focus on factual, historical, or broad informative content rather than individual personal experiences.","example":"Correct topics: How electricity changed the 1900s; The history of the lightbulb. Incorrect: The time I dropped my phone flashlight.","strategyClue":"Ask yourself if the statement describes a broad, historical, or societal fact that an encyclopedia would cover, or if it describes a private story that only happened to one person.","link":"","linkText":""}},{"id":"punctuation-apostrophes-possessives-q0024","version":2,"contentHash":"sha256:83330e5e1ce5e048b2fd542db316251c3a94d8a4d29a8cd3ac69740e178e6ad8","question":"Which of the underlined words in the following sentences is an example of a regular possessive noun?","choices":["Someone’s parked in my parking spot.","The dancer’s costume has been torn.","Check in all of the literature book’s by three o’clock.","The neighbor dog’s barked at all the strangers walking by."],"correct":1,"explanation":{"correct":"Answer: The dancer’s costume has been torn. This sentence uses a regular possessive noun because 'dancer's' shows that the costume belongs to the dancer, following the standard rule of adding an apostrophe and 's' to a singular noun.","incorrect":[{"choice":"Someone’s parked in my parking spot.","category":"contraction error","reason":"In this sentence, 'someone's' is a contraction of 'someone has,' not a possessive noun. The apostrophe represents missing letters, not ownership."},"",{"choice":"Check in all of the literature book’s by three o’clock.","category":"incorrect pluralization","reason":"The sentence intends to refer to more than one book. 'Book’s' is possessive, but 'books' (plural) is needed here. Possession is not being shown."},{"choice":"The neighbor dog’s barked at all the strangers walking by.","category":"verb contraction confusion","reason":"The 's in 'dog’s' here stands for the verb 'has,' meaning 'the dog has barked.' It is a contraction, not a possessive noun showing ownership."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","mechanics","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-possessives","sequence":24,"sourceFile":"Basic-1_language Usage.pdf","sourceQuestionNumber":7,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"A possessive noun uses an apostrophe and an 's' to show that a person, place, or thing owns something else. If the word shows ownership, it is possessive; if it shows a shortened verb like 'is' or 'has,' it is a contraction.","example":"The cat's toy (possessive), The cat's running (contraction for 'cat is'), The dog's bowl (possessive).","strategyClue":"Replace the word containing the apostrophe with 'is' or 'has'. If the sentence still makes sense, it is a contraction, not a possessive noun.","link":"","linkText":""}},{"id":"punctuation-apostrophes-possessives-q0025","version":2,"contentHash":"sha256:2a5290bc0609a75e2af1d1a635651e9498702bdaa127a20073b8f39a1fd11802","question":"Choose the correct pronoun to complete the sentence below. Martha picked up the dog from the vet but forgot _____ bone.","choices":["our","we’s","his","them’s"],"correct":2,"explanation":{"correct":"Answer: his. Since 'the dog' is the noun the pronoun refers back to, we use the possessive pronoun 'his' to show that the bone belongs to the dog.","incorrect":[{"choice":"our","category":"incorrect possessive pronoun","reason":"Using 'our' implies that the speaker and someone else own the dog's bone, which does not match the context of the dog being at the vet."},{"choice":"we’s","category":"nonexistent pronoun form","reason":"The word 'we’s' is not a real word in the English language. Possessive pronouns for people or animals follow specific forms like 'his', 'her', or 'its'."},"",{"choice":"them’s","category":"incorrect pronoun usage","reason":"The word 'them’s' is not standard English. Use possessive pronouns like 'his' when describing something belonging to a singular noun like a dog."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","mechanics","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-possessives","sequence":25,"sourceFile":"Basic-2_language Usage.pdf","sourceQuestionNumber":10,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"Possessive pronouns are used to show ownership. They replace nouns so you don't have to repeat them.","example":"The girl lost her hat. The dog chewed his toy. The cat licked its paw.","strategyClue":"Identify who or what owns the object (the bone) and choose the pronoun that correctly shows ownership for that singular noun.","link":"","linkText":""}},{"id":"punctuation-apostrophes-possessives-q0026","version":2,"contentHash":"sha256:f1c8f72ed31f89edee178b3672bf05f876cf8693f5c5f831e28af7796b23f4f6","question":"Look at the listof instructions for how to make a bow l of cereal. 1. Getout a bowl and a spoon. 2. Pour the cereal into the bowl. 3. 4. Use a spoon to eat the cereal. Which direction belongs on line 3?","choices":["Pour milk on the cereal.","Wash your bowl.","Go to the kitchen.","Buy the cereal at the store."],"correct":0,"explanation":{"correct":"Answer: Pour milk on the cereal. This step logically follows pouring the dry cereal into the bowl but precedes eating it, completing the standard sequence for preparing a bowl of cereal.","incorrect":["",{"choice":"Wash your bowl.","category":"illogical sequence","reason":"While washing a bowl is a healthy habit, it should happen before you get the bowl out to use it, not after the cereal is already in it."},{"choice":"Go to the kitchen.","category":"out of order","reason":"You must already be in the kitchen to follow the first two steps of getting a bowl and pouring cereal. This step is out of place."},{"choice":"Buy the cereal at the store.","category":"wrong timeline","reason":"Buying cereal is a task that must be completed long before you start the preparation steps of getting a bowl and pouring the cereal."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"passage-context","skills":["punctuation","mechanics","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-possessives","sequence":26,"sourceFile":"Basic-2_language Usage.pdf","sourceQuestionNumber":42,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"Sequencing involves putting the steps of a process in the correct logical order so that the result makes sense.","example":"Correct: 1. Put on socks. 2. Put on shoes. Incorrect: 1. Put on shoes. 2. Put on socks.","strategyClue":"Imagine performing the action yourself. Ask, 'What must happen to turn the dry cereal into a finished meal?' and look for the missing piece that links the existing steps.","link":"","linkText":""}},{"id":"punctuation-apostrophes-possessives-q0027","version":2,"contentHash":"sha256:a2a0f84236d14adf6979dbc777e629d6ecc4fa6d1beaed2dd1f100e6ba706c62","question":"Pick the listof items that typically belongs in a pizza.","choices":["flour, cheese, ketchup","tomatoes, caramel, cheese","cheese, flour, sauce","sauce, syrup, flour"],"correct":2,"explanation":{"correct":"Answer: cheese, flour, sauce. Pizza dough is made from flour, and the topping and base rely on cheese and sauce. These ingredients are standard components of a typical pizza.","incorrect":[{"choice":"flour, cheese, ketchup","category":"Incorrect food item","reason":"While flour and cheese are pizza ingredients, ketchup is a condiment typically used for fries or hot dogs, not as a pizza sauce."},{"choice":"tomatoes, caramel, cheese","category":"Inappropriate food item","reason":"Tomatoes and cheese belong on pizza, but caramel is a sugary candy topping that does not belong on a savory pizza."},"",{"choice":"sauce, syrup, flour","category":"Inappropriate food item","reason":"Sauce and flour are correct, but syrup is a sweet breakfast topping used for pancakes or waffles, not for pizza."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","mechanics","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-possessives","sequence":27,"sourceFile":"Proficient-2_language Usage.pdf","sourceQuestionNumber":18,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"A list should include items that are logically related or grouped together by a common purpose, like ingredients in a recipe.","example":"Pizza ingredients: dough, sauce, cheese. Fruit salad: apples, grapes, melon.","strategyClue":"Think about the main purpose of the group; imagine each ingredient being added to the same dish and ask yourself if it would taste right together.","link":"","linkText":""}},{"id":"punctuation-apostrophes-possessives-q0028","version":2,"contentHash":"sha256:009db23dd06be6a48d655e5b5ddecbb897c88d471fd60114e896f1d5ae6d7280","question":"Which word is a possessive noun? We were jumping on the school’s trampolines during our gym classes.","choices":["we","school’s","trampolines","classes"],"correct":1,"explanation":{"correct":"Answer: school’s. A possessive noun shows ownership and includes an apostrophe. Because the trampolines belong to the school, we add an apostrophe and an 's' to the word 'school'.","incorrect":[{"choice":"we","category":"personal pronoun","reason":"'We' is a pronoun used as a subject, not a noun. It does not show ownership of anything in the sentence."},"",{"choice":"trampolines","category":"plural noun","reason":"'Trampolines' is a plural noun that shows there is more than one trampoline, but it lacks an apostrophe and does not indicate ownership."},{"choice":"classes","category":"plural noun","reason":"'Classes' is a plural noun. While it ends in 's', it does not show that the gym classes own anything, nor does it have an apostrophe."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","mechanics","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"punctuation-apostrophes-possessives","sequence":28,"sourceFile":"Proficient-2_language Usage.pdf","sourceQuestionNumber":31,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"A possessive noun shows who or what owns something by adding an apostrophe and an 's' to the end of the noun.","example":"The dog's bone (the bone belongs to the dog); The teacher's desk (the desk belongs to the teacher).","strategyClue":"Look for a word that answers the question 'Whose?' and contains an apostrophe. If a word is just plural, it will not have an apostrophe.","link":"","linkText":""}}],"metadata":{"gradesSupported":[3,4,5,6],"difficultiesSupported":["easy","medium","hard"],"selectorPolicy":"grade+difficulty selects exact matches first, then nearby grade-appropriate practice to fill the configured mission length"}}}
  );
})();
